#include "stdafx.h"#include "ControlBuilder.h"#include "CBPool.h"extern KCBPool g_Pool;extern int g_All2MomState;void KControlBuilder::EnableMomStateDEVCTL(){  g_All2MomState = g_Pool.GetCtrlCount();}enum{  eFirstStepsTest = 50,};int KControlBuilder::StepTL(double dt_sec){  if( !m_entryModule )    return -1;  DWORD s = 0;  if( m_nFirstSteps < eFirstStepsTest )    s = GetTickCount();  SStepCalcParams parm;  parm = dt_sec;  parm.usePhases = m_usePhases;  m_entryModule->StepT( parm );  if( g_All2MomState>0 )    --g_All2MomState;  if( m_nFirstSteps < eFirstStepsTest )  {    DWORD d = GetTickCount() - s;    char szDebug[128];    sprintf_s( szDebug, "время шага №% d CB (%s) %dms, при dt_sec=%0.5f ms\n", m_nFirstSteps, m_szPrjName, d, dt_sec );    OutputDebugString( szDebug );    ++m_nFirstSteps;  }  return 0;}